/* emit-caller.c -- the abi_tools package's `emit-caller` tool
 * (EXTERNAL-COMPILER-TOOLS-AND-TARGET-PACKAGES-MILESTONE-1.md, experiment
 * D): from one Botlish native library's manifest (schema 2), a C program
 * that calls the library's exports.
 *
 *   botlish tool -out DIR -artifact LIB.manifest.json emit-caller
 *
 * writes DIR/LIB_caller.c and DIR/LIB_caller.build.json (what to compile it
 * with: the library's include directory, its static archive and the link
 * arguments the manifest states). The caller reads calls from standard
 * input and writes their outcomes (the generated file's own comment says
 * how). Every C type, every release function and the order of every
 * argument come from the manifest; a manifest this tool cannot read
 * completely is refused (toolkit.h). The output depends on the manifest
 * only: the same manifest gives the same bytes. */
#include "toolkit.h"

static void sanitize_comment(tk_text *t, const char *s) {
    for (; *s; s++) {
        if (s[0] == '*' && s[1] == '/') tk_printf(t, "* /");
        else tk_printf(t, "%c", *s);
    }
}

static void emit_caller(const tk_library *lib, tk_text *t) {
    const char *L = lib->library;
    tk_printf(t,
        "/* %s_caller.c -- a command-line caller of the Botlish native library %s,\n"
        " * generated by abi_tools emit-caller from %s.manifest.json (runtime ABI\n"
        " * %s). Do not edit: regenerate it.\n"
        " *\n"
        " * Reads calls from standard input, one per line: an export's name, then its\n"
        " * arguments, separated by tabs (in an argument \\\\t, \\\\n and \\\\\\\\ are a tab, a\n"
        " * newline and a backslash; \"@\" alone is the previous call's str result).\n"
        " * Writes one line per call: the name, then \"ok\", the result's type and\n"
        " * value, or \"error\", the status, the error's identity and its fields\n"
        " * (NAME=VALUE), tab-separated and escaped the same way. Lines starting\n"
        " * with # and empty lines are skipped. Exit status 0, or 1 when a line is\n"
        " * no call of an export.\n"
        " *\n"
        " * Exports:\n",
        L, L, L, lib->runtimeAbi);
    for (size_t e = 0; e < lib->nexports; e++) {
        tk_printf(t, " *   ");
        sanitize_comment(t, lib->exports[e].botlish);
        tk_printf(t, "\n");
    }
    tk_printf(t, " */\n"
        "#define _POSIX_C_SOURCE 200809L\n#include <errno.h>\n#include <stdbool.h>\n#include <stdint.h>\n#include <stdio.h>\n"
        "#include <stdlib.h>\n#include <string.h>\n\n#include \"%s\"\n\n", lib->header);
    tk_printf(t,
        "static uint8_t *last;\n"
        "static size_t last_len;\n\n"
        "static inline void put(const uint8_t *p, size_t n) {\n"
        "    for (size_t i = 0; i < n; i++) {\n"
        "        if (p[i] == '\\t') fputs(\"\\\\t\", stdout);\n"
        "        else if (p[i] == '\\n') fputs(\"\\\\n\", stdout);\n"
        "        else if (p[i] == '\\\\') fputs(\"\\\\\\\\\", stdout);\n"
        "        else putchar(p[i]);\n"
        "    }\n"
        "}\n\n"
        "/* S unescaped in place; its length. */\n"
        "static inline size_t unescape(char *s) {\n"
        "    size_t o = 0;\n"
        "    for (size_t i = 0; s[i]; i++) {\n"
        "        if (s[i] == '\\\\' && s[i + 1] == 't') { s[o++] = '\\t'; i++; }\n"
        "        else if (s[i] == '\\\\' && s[i + 1] == 'n') { s[o++] = '\\n'; i++; }\n"
        "        else if (s[i] == '\\\\' && s[i + 1] == '\\\\') { s[o++] = '\\\\'; i++; }\n"
        "        else s[o++] = s[i];\n"
        "    }\n"
        "    s[o] = 0;\n"
        "    return o;\n"
        "}\n\n"
        "static inline int arg_int(const char *s, int64_t *v) {\n"
        "    char *end;\n"
        "    errno = 0;\n"
        "    long long x = strtoll(s, &end, 10);\n"
        "    if (!*s || *end || errno) return 0;\n"
        "    *v = (int64_t)x;\n"
        "    return 1;\n"
        "}\n\n"
        "static inline int arg_bool(const char *s, bool *v) {\n"
        "    if (!strcmp(s, \"true\")) { *v = true; return 1; }\n"
        "    if (!strcmp(s, \"false\")) { *v = false; return 1; }\n"
        "    return 0;\n"
        "}\n\n"
        "static inline int arg_float64(const char *s, double *v) {\n"
        "    char *end;\n"
        "    *v = strtod(s, &end);\n"
        "    return *s && !*end;\n"
        "}\n\n"
        "/* A str argument: its bytes, or the previous str result for \"@\". */\n"
        "static inline void arg_str(char *s, size_t len, const uint8_t **p, size_t *n) {\n"
        "    if (len == 1 && s[0] == '@' && last) { *p = last; *n = last_len; return; }\n"
        "    *p = (const uint8_t *)s;\n"
        "    *n = len;\n"
        "}\n\n"
        "static inline void keep(const uint8_t *p, size_t n) {\n"
        "    free(last);\n"
        "    last = malloc(n + 1);\n"
        "    if (!last) { fputs(\"out of memory\\n\", stderr); exit(70); }\n"
        "    memcpy(last, p, n);\n"
        "    last_len = n;\n"
        "}\n\n");
    tk_printf(t,
        "static const char *status_name(int32_t status) {\n"
        "    switch (status) {\n"
        "    case %s_STATUS_OK: return \"ok\";\n"
        "    case %s_STATUS_DECLARED: return \"declared\";\n"
        "    case %s_STATUS_RUNTIME: return \"runtime\";\n"
        "    case %s_STATUS_BOUNDARY: return \"boundary\";\n"
        "    case %s_STATUS_INVOCATION: return \"invocation\";\n"
        "    case %s_STATUS_INTERNAL: return \"internal\";\n"
        "    default: return \"unknown\";\n"
        "    }\n"
        "}\n\n", L, L, L, L, L, L);
    tk_printf(t,
        "/* Writes the failed call NAME's outcome, and releases its error E (the\n"
        " * caller owns it: RELEASE, the manifest's release function). */\n"
        "static void report(const char *name, int32_t status, %s_error *e, int32_t (*release)(%s_error **)) {\n"
        "    printf(\"%%s\\terror\\t%%s\", name, status_name(status));\n"
        "    if (e) {\n"
        "        const uint8_t *p;\n"
        "        size_t n;\n"
        "        if (%s_error_identity(e, &p, &n) == %s_STATUS_OK) { putchar('\\t'); put(p, n); }\n"
        "        size_t count = %s_error_field_count(e);\n"
        "        for (size_t i = 0; i < count; i++) {\n"
        "            putchar('\\t');\n"
        "            if (%s_error_field_name(e, i, &p, &n) == %s_STATUS_OK) put(p, n);\n"
        "            putchar('=');\n"
        "            switch (%s_error_field_type(e, i)) {\n"
        "            case %s_FIELD_INT: { int64_t v; if (%s_error_field_int(e, i, &v) == %s_STATUS_OK) printf(\"%%lld\", (long long)v); else fputs(\"(beyond int64_t)\", stdout); break; }\n"
        "            case %s_FIELD_BOOL: { bool v = false; %s_error_field_bool(e, i, &v); fputs(v ? \"true\" : \"false\", stdout); break; }\n"
        "            case %s_FIELD_FLOAT64: { double v = 0; %s_error_field_float64(e, i, &v); printf(\"%%.17g\", v); break; }\n"
        "            case %s_FIELD_STR: { if (%s_error_field_str(e, i, &p, &n) == %s_STATUS_OK) put(p, n); break; }\n"
        "            default: fputs(\"(other)\", stdout);\n"
        "            }\n"
        "        }\n"
        "        release(&e);\n"
        "    }\n"
        "    putchar('\\n');\n"
        "}\n\n",
        L, L, L, L, L, L, L, L, L, L, L, L, L, L, L, L, L, L);
    tk_printf(t,
        "int main(void) {\n"
        "    %s_instance *in;\n"
        "    %s_error *created = NULL;\n"
        "    int32_t status = %s(&in, &created);\n"
        "    if (status != %s_STATUS_OK) {\n"
        "        report(\"%s\", status, created, %s_error_release);\n"
        "        return 1;\n"
        "    }\n"
        "    char *line = NULL;\n"
        "    size_t size = 0;\n"
        "    ssize_t got;\n"
        "    int bad = 0;\n"
        "    long number = 0;\n"
        "    while ((got = getline(&line, &size, stdin)) >= 0) {\n"
        "        number++;\n"
        "        if (got > 0 && line[got - 1] == '\\n') line[--got] = 0;\n"
        "        if (!got || line[0] == '#') continue;\n"
        "        char *fields[64];\n"
        "        size_t lens[64];\n"
        "        size_t count = 0;\n"
        "        for (char *f = line;; ) {\n"
        "            char *tab = strchr(f, '\\t');\n"
        "            if (tab) *tab = 0;\n"
        "            if (count == 64) { count++; break; }\n"
        "            fields[count] = f;\n"
        "            lens[count] = unescape(f);\n"
        "            count++;\n"
        "            if (!tab) break;\n"
        "            f = tab + 1;\n"
        "        }\n"
        "        if (count > 64) { fprintf(stderr, \"line %%ld: too many arguments\\n\", number); bad = 1; continue; }\n",
        L, L, lib->create, L, lib->create, L);
    for (size_t e = 0; e < lib->nexports; e++) {
        const tk_export *x = &lib->exports[e];
        tk_printf(t, "        if (!strcmp(fields[0], \"%s\")) {\n", x->name);
        tk_printf(t, "            /* ");
        sanitize_comment(t, x->botlish);
        tk_printf(t, " */\n");
        tk_printf(t,
            "            if (count != %zu) { fprintf(stderr, \"line %%ld: %s takes %zu argument%s\\n\", number); bad = 1; continue; }\n",
            x->nparams + 1, x->name, x->nparams, x->nparams == 1 ? "" : "s");
        for (size_t p = 0; p < x->nparams; p++) {
            switch (x->params[p].type) {
            case T_INT:
                tk_printf(t, "            int64_t a%zu;\n            if (!arg_int(fields[%zu], &a%zu)) { fprintf(stderr, \"line %%ld: %s: argument %s is no int64_t\\n\", number); bad = 1; continue; }\n", p, p + 1, p, x->name, x->params[p].name);
                break;
            case T_BOOL:
                tk_printf(t, "            bool a%zu;\n            if (!arg_bool(fields[%zu], &a%zu)) { fprintf(stderr, \"line %%ld: %s: argument %s is no bool\\n\", number); bad = 1; continue; }\n", p, p + 1, p, x->name, x->params[p].name);
                break;
            case T_FLOAT64:
                tk_printf(t, "            double a%zu;\n            if (!arg_float64(fields[%zu], &a%zu)) { fprintf(stderr, \"line %%ld: %s: argument %s is no double\\n\", number); bad = 1; continue; }\n", p, p + 1, p, x->name, x->params[p].name);
                break;
            case T_STR:
                tk_printf(t, "            const uint8_t *a%zu;\n            size_t a%zu_len;\n            arg_str(fields[%zu], lens[%zu], &a%zu, &a%zu_len);\n", p, p, p + 1, p + 1, p, p);
                break;
            default:
                break;
            }
        }
        switch (x->result) {
        case T_INT: tk_printf(t, "            int64_t r;\n"); break;
        case T_BOOL: tk_printf(t, "            bool r;\n"); break;
        case T_FLOAT64: tk_printf(t, "            double r;\n"); break;
        case T_STR: tk_printf(t, "            %s r = {0};\n", lib->bytesType); break;
        default: break;
        }
        tk_printf(t, "            %s_error *e = NULL;\n            int32_t s = %s(in", L, x->symbol);
        for (size_t p = 0; p < x->nparams; p++) {
            if (x->params[p].type == T_STR) tk_printf(t, ", a%zu, a%zu_len", p, p);
            else tk_printf(t, ", a%zu", p);
        }
        if (x->result != T_UNIT) tk_printf(t, ", &r");
        tk_printf(t, ", &e);\n");
        tk_printf(t, "            if (s != %s_STATUS_OK) { report(\"%s\", s, e, %s); continue; }\n", L, x->name, x->errorRelease);
        switch (x->result) {
        case T_INT: tk_printf(t, "            printf(\"%s\\tok\\tint\\t%%lld\\n\", (long long)r);\n", x->name); break;
        case T_BOOL: tk_printf(t, "            printf(\"%s\\tok\\tbool\\t%%s\\n\", r ? \"true\" : \"false\");\n", x->name); break;
        case T_FLOAT64: tk_printf(t, "            printf(\"%s\\tok\\tfloat64\\t%%.17g\\n\", r);\n", x->name); break;
        case T_STR:
            tk_printf(t,
                "            fputs(\"%s\\tok\\tstr\\t\", stdout);\n"
                "            put(r.ptr, r.len);\n"
                "            putchar('\\n');\n"
                "            keep(r.ptr, r.len);\n"
                "            %s(&r); /* the caller owns a str result (the manifest's release) */\n",
                x->name, x->resultRelease);
            break;
        default: tk_printf(t, "            printf(\"%s\\tok\\tunit\\n\");\n", x->name); break;
        }
        tk_printf(t, "            continue;\n        }\n");
    }
    tk_printf(t,
        "        fprintf(stderr, \"line %%ld: %%s is no export of %s\\n\", number, fields[0]);\n"
        "        bad = 1;\n"
        "    }\n"
        "    free(line);\n"
        "    free(last);\n"
        "    %s(in);\n"
        "    fflush(stdout);\n"
        "    return bad;\n"
        "}\n", L, lib->destroy);
}

static void emit_build(const tk_library *lib, tk_text *t) {
    tk_printf(t, "{\n  \"generator\": \"abi_tools emit-caller 0.1.0\",\n  \"library\": ");
    tk_json_text(t, lib->library);
    tk_printf(t, ",\n  \"source\": ");
    char source[300];
    snprintf(source, sizeof source, "%s_caller.c", lib->library);
    tk_json_text(t, source);
    tk_printf(t, ",\n  \"includeDirs\": [");
    tk_json_text(t, lib->dir);
    tk_printf(t, "],\n  \"inputs\": [");
    char *archive = tk_join(lib->dir, lib->staticLib);
    tk_json_text(t, archive);
    free(archive);
    tk_printf(t, "],\n  \"link\": [");
    int first = 1;
    for (size_t i = 0; i < lib->ndependencies; i++) {
        tk_printf(t, "%s", first ? "" : ", ");
        tk_json_text(t, lib->dependencies[i]);
        first = 0;
    }
    for (size_t i = 0; i < lib->nlink; i++) {
        tk_printf(t, "%s", first ? "" : ", ");
        tk_json_text(t, lib->link[i]);
        first = 0;
    }
    tk_printf(t, "]\n}\n");
}

int main(int argc, char **argv) {
    tk_request r = tk_open_request("emit-caller");
    if (argc > 1) tk_die(64, "TOOL-USAGE", NULL, "emit-caller takes no arguments (found \"%s\")", argv[1]);
    tk_library lib = tk_request_library(&r);
    tk_text source = {0}, build = {0};
    emit_caller(&lib, &source);
    emit_build(&lib, &build);
    char name[300];
    snprintf(name, sizeof name, "%s_caller.c", lib.library);
    tk_write(r.output, name, &source);
    snprintf(name, sizeof name, "%s_caller.build.json", lib.library);
    tk_write(r.output, name, &build);
    printf("emit-caller: %s/%s_caller.c, %zu export%s of %s\n", r.output, lib.library, lib.nexports, lib.nexports == 1 ? "" : "s", lib.library);
    tk_finish();
    return 0;
}
